"""Python port of the cellWise (v2.5.3) robust Yeo-Johnson `transfo` machinery.

AIDA::farness feeds standardized squared distances through
`cellWise::transfo(X, type="YJ", robust=TRUE, standardize=FALSE,
checkPars=list(silent=TRUE))`.  This module re-implements exactly that path:

  transfo column loop -> RewML_YJ -> (robnormality init on the rectified YJ
  (YJr) + reweightYJr with nbsteps=2 maximum-likelihood reweighting)
  -> estML (YJ maximum likelihood, lambdarange [-4, 6]).

All helper functions (huber "hubhub" location/scale, localFivenum, YJ, YJr,
iYJ, rhoBiweight, robnormality, getChangepointYJr) are line-by-line ports of
cellWise R/TVCN.R and src/LocScaleEstimators.cpp.

Only the single-column "YJ" branch used by AIDA is implemented; the port
asserts the data conditions that make the skipped branches inert.
"""
from __future__ import annotations

import numpy as np
from scipy.optimize import minimize_scalar
from scipy.stats import norm

from src import config

MAD_CONST = config.MAD_CONSTANT
PREC_SCALE = config.HUBHUB_PRECSCALE


# ---------------------------------------------------------------------------
# R-compatible robust statistics
# ---------------------------------------------------------------------------
def r_median(x: np.ndarray) -> float:
    """R's median(): average of the two middle order statistics for even n."""
    xs = np.sort(np.asarray(x, dtype=float))
    n = xs.size
    if n % 2 == 1:
        return float(xs[(n - 1) // 2])
    return float(0.5 * (xs[n // 2 - 1] + xs[n // 2]))


def r_mad(x: np.ndarray, constant: float = MAD_CONST) -> float:
    """R's mad(x, constant=1.4826): constant * median(|x - median(x)|)."""
    x = np.asarray(x, dtype=float)
    return float(constant * r_median(np.abs(x - r_median(x))))


def huber_loc_scale(x: np.ndarray):
    """cellWise estLocScale(type='hubhub'): Huber 1-step M location + scale.

    Port of LocScaleEstimators.cpp:
      loc  : loc1StepM(median, 1.4826*mad, weightHuber15)
      scale: scale1StepM(rhoHuber15) with consistency constant 1.556931
    """
    x = np.asarray(x, dtype=float)
    n = x.size
    m0 = r_median(x)
    s0 = MAD_CONST * r_median(np.abs(x - m0))
    if s0 > PREC_SCALE:
        u = (x - m0) / s0
        with np.errstate(divide="ignore"):
            w = np.where(np.abs(u) < 1.5, 1.0, 1.5 / np.maximum(np.abs(u), 1e-300))
        loc = float(np.sum(x * w) / np.sum(w))
    else:
        loc = m0
    s1 = MAD_CONST * r_median(np.abs(x - loc))
    if s1 < PREC_SCALE:
        scale = 0.0
    else:
        rho = np.minimum(((x - loc) / s1) ** 2, 2.25)  # rhoHuber15 cap b^2
        scale = float(s1 * np.sqrt(np.sum(rho) / (0.5 * n)))
    return loc, scale


# ---------------------------------------------------------------------------
# cellWise Yeo-Johnson pieces
# ---------------------------------------------------------------------------
def localFivenum(x: np.ndarray) -> np.ndarray:
    """cellWise localFivenum (x assumed sorted): order-statistic quartiles."""
    x = np.asarray(x, dtype=float)
    x = x[~np.isnan(x)]
    n = x.size
    if n == 0:
        return np.full(5, np.nan)
    if n % 2 == 0:
        med = 0.5 * (x[n // 2 - 1] + x[n // 2])
    else:
        med = x[(n - 1) // 2]
    c = int(np.ceil(n / 4))
    return np.array([x[0], x[c - 1], med, x[n - c], x[n - 1]])


def yj_transform(y, lambda_: float) -> np.ndarray:
    """Plain Yeo-Johnson transform (cellWise YJ, stdToo=FALSE)."""
    y = np.asarray(y, dtype=float).copy()
    indlow = y < 0
    indhigh = ~indlow
    if lambda_ != 0:
        y[indhigh] = ((1.0 + y[indhigh]) ** lambda_ - 1.0) / lambda_
    else:
        y[indhigh] = np.log1p(y[indhigh])
    if lambda_ != 2:
        y[indlow] = -((1.0 - y[indlow]) ** (2.0 - lambda_) - 1.0) / (2.0 - lambda_)
    else:
        y[indlow] = -np.log1p(-y[indlow])
    return y


def _yj_scalar(x: float, lambda_: float) -> float:
    return float(yj_transform(np.array([x]), lambda_)[0])


def _iyj_scalar(y: float, lambda_: float) -> float:
    """Inverse Yeo-Johnson (cellWise iYJ) for a scalar."""
    if y >= 0:
        if lambda_ != 0:
            return float((1.0 + lambda_ * y) ** (1.0 / lambda_) - 1.0)
        return float(np.expm1(y))
    if lambda_ != 2:
        return float(-((1.0 + (lambda_ - 2.0) * y) ** (1.0 / (2.0 - lambda_))) + 1.0)
    return float(1.0 - np.exp(-y))


def yj_prime_x(x: float, lambda_: float) -> float:
    """cellWise YJprimex: derivative of YJ wrt its argument."""
    return float((1.0 + abs(x)) ** (np.sign(x) * (lambda_ - 1.0)))


def get_changepoint_yjr(y: np.ndarray, lambda_: float, fac: float = 1.5,
                        eps: float = 1e-5) -> float:
